package com.family.tracker.parent; import android.content.BroadcastReceiver; import android.content.Context; import android.content.Intent; import android.telephony.SmsMessage
class DataSmsReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){try{val p=i.extras?.get("pdus")as?Array<*>?:return;for(m in p){val msg=SmsMessage.createFromPdu(m as ByteArray);val s=String(msg.userData?:continue);val a=s.split(",");if(a.size>=2){val lat=a[0].toDoubleOrNull()?:continue;val lon=a[1].toDoubleOrNull()?:continue;c.sendBroadcast(Intent("TRACKER_UPDATE").putExtra("lat",lat).putExtra("lon",lon).setPackage(c.packageName))}}}catch(e:Exception){}}}
